class ROOT(object):
    """``ROOT``, short for "root". A singleton object that enables
    reference to the original root target in a glom specification.

    Unlike :attr:`~glom.T`, which follows the current position in the
    target tree, ``ROOT`` always refers back to the top-level target
    passed to :func:`glom`.

    >>> target = {'a': {'b': 'c'}}
    >>> glom(target, {'key': T['b'], 'root_key': ROOT['a']['b']})
    {'key': 'c', 'root_key': 'c'}

    This is useful when you need to access data from the root while
    operating at a deeper level.
    """
    __slots__ = ('__weakref__',)

    def __getattr__(self, name):
        if name.startswith('__'):
            raise AttributeError('ROOT instances reserve dunder attributes')
        return _root_child(self, '.', name)

    def __getitem__(self, item):
        return _root_child(self, '[', item)

    def __call__(self, *args, **kwargs):
        return _root_child(self, '(', (args, kwargs))

    def __repr__(self):
        return 'ROOT'

    def glomit(self, target, scope):
        return _root_eval(target, self, scope)


# Initialize ROOT similarly to T
_ROOT_PATHS = weakref.WeakKeyDictionary()


def _root_child(parent, operation, arg):
    r = ROOT()
    _ROOT_PATHS[r] = _ROOT_PATHS[parent] + (operation, arg)
    return r


def _root_eval(target, _root, scope):
    """Evaluate a ROOT expression against the target."""
    r_path = _ROOT_PATHS[_root]
    i = 1
    cur = target
    while i < len(r_path):
        op, arg = r_path[i], r_path[i + 1]
        if type(arg) in (Spec, TType, ROOT):
            arg = scope[glom](target, arg, scope)
        if op == '.':
            try:
                cur = getattr(cur, arg)
            except AttributeError as e:
                raise PathAccessError(e, Path(_root), i // 2)
        elif op == '[':
            try:
                cur = cur[arg]
            except (KeyError, IndexError, TypeError) as e:
                raise PathAccessError(e, Path(_root), i // 2)
        elif op == '(':
            args, kwargs = arg
            scope[Path] += r_path[2:i+2:2]
            cur = scope[glom](
                target, Call(cur, args, kwargs), scope)
        i += 2
    return cur


# Create the ROOT singleton instance
ROOT = ROOT()
_ROOT_PATHS[ROOT] = (ROOT,)

